import * as z from "zod/v4";
import { registerContinuationChannel } from "../../internal/continuation-registration.js";
import { createResourceChannel } from "../../internal/resource-channel.js";
import { RUN_CREATED_EVENT_TYPE } from "./types.js";
const runResourceSchema = z
    .object({
    name: z.string().min(1),
    environment: z.string().min(1),
    services: z.array(z.string().min(1)).min(1),
    deployVersion: z.string().min(1),
    request: z.object({ note: z.string().optional() }).passthrough().optional(),
    planRevision: z.string().min(1).optional(),
    createTime: z.string().min(1).optional(),
})
    .passthrough();
const runCreatedEventSchema = z.object({
    eventId: z.string().min(1),
    eventType: z.literal(RUN_CREATED_EVENT_TYPE),
    teamId: z.string().min(1),
    occurredAtMs: z.number().int().nonnegative(),
    run: runResourceSchema,
});
const pack = createResourceChannel({
    kind: "runs",
    eventTypes: [RUN_CREATED_EVENT_TYPE],
    eventSchema: runCreatedEventSchema,
    replayDescription: "Replay a run created event.",
    invalidError: "invalid run event",
});
export function runsChannel(options) {
    return pack.channel(options);
}
export function getRunsChannelOptions(definition) {
    return pack.getOptions(definition);
}
registerContinuationChannel({
    kind: "runs",
    getOptions: getRunsChannelOptions,
    usesDeclaredEvents: true,
});
